package com.kynsoft.report.infrastructure.services;
import com.kynsoft.report.domain.dto.*; import com.kynsoft.report.infrastructure.entity.*; import com.kynsoft.report.infrastructure.repository.command.*; import com.kynsoft.report.infrastructure.repository.query.*; import com.kynsoft.report.infrastructure.security.*; import jakarta.transaction.Transactional; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*;
@Service @Transactional public class DocumentoCajaControlService {
 private static final List<Integer> DENOMS=List.of(5,10,20,50,100,200,500,1000,2000,5000,10000,20000); private static final double EPS=0.000001d;
 private final DocumentoCajaWriteDataJPARepository write; private final DocumentoCajaReadDataJPARepository read; private final FincaReadDataJPARepository fincas; private final MovimientoCajaWriteDataJPARepository cajaWrite; private final MovimientoCajaDenominacionWriteDataJPARepository detalleWrite; private final SaldoCajaDenominacionWriteDataJPARepository saldoWrite; private final AuditoriaTransaccionalService auditoria;
 public DocumentoCajaControlService(DocumentoCajaWriteDataJPARepository write, DocumentoCajaReadDataJPARepository read,FincaReadDataJPARepository fincas,MovimientoCajaWriteDataJPARepository cajaWrite,MovimientoCajaDenominacionWriteDataJPARepository detalleWrite,SaldoCajaDenominacionWriteDataJPARepository saldoWrite,AuditoriaTransaccionalService auditoria){this.write=write;this.read=read;this.fincas=fincas;this.cajaWrite=cajaWrite;this.detalleWrite=detalleWrite;this.saldoWrite=saldoWrite;this.auditoria=auditoria;}
 public UUID crear(DocumentoCajaRequest r){ validar(r); TenantValidator.validateWriteAccess(r.getFincaId()); finca(r.getFincaId()); Map<Integer,Integer> denoms=Boolean.TRUE.equals(r.getRegistrarMovimientoCaja())?denominaciones(r):Map.of(); DocumentoCaja d=new DocumentoCaja(); d.setId(UUID.randomUUID());d.setNumero(write.siguienteNumero());d.setFincaId(r.getFincaId());d.setTipo(r.getTipo());d.setFecha(r.getFecha()==null?LocalDateTime.now():r.getFecha());d.setImporte(r.getImporte());d.setBeneficiario(t(r.getBeneficiario()));d.setConcepto(t(r.getConcepto()));d.setEntregadoPor(t(r.getEntregadoPor()));d.setRecibidoPor(t(r.getRecibidoPor()));d.setAutorizadoPor(t(r.getAutorizadoPor()));d.setReferencia(t(r.getReferencia()));d.setObservaciones(t(r.getObservaciones()));d.setEstado(EstadoDocumentoControl.ACTIVO);d.setUsuarioId(TenantContext.getUsuarioId());write.save(d); Map<String,Object> datos=new LinkedHashMap<>();datos.put("fincaId",d.getFincaId());datos.put("numero",d.getNumero());datos.put("tipo",d.getTipo());datos.put("importe",d.getImporte());datos.put("referencia",d.getReferencia());datos.put("movimientoCaja",!denoms.isEmpty());auditoria.registrarDespuesDeConfirmar(TipoAccion.CREATE,"DOCUMENTO_CAJA",d.getId(),"Emisión de documento de caja",null,datos); if(!denoms.isEmpty())movimientoCaja(d,r.getSentidoCaja(),denoms); return d.getId(); }
 public void anular(UUID id,String observaciones){DocumentoCaja d=write.findById(id).orElseThrow(()->new IllegalArgumentException("Documento de caja no encontrado."));TenantValidator.validateWriteAccess(d.getFincaId()); if(d.getEstado()==EstadoDocumentoControl.ANULADO) throw new IllegalArgumentException("El documento ya fue anulado."); if(cajaWrite.existsByDocumentoCajaId(d.getId()))throw new IllegalArgumentException("Este documento ya afectó Caja; no puede anularse. Emita un documento de reversión con el sentido contrario para conservar la trazabilidad.");EstadoDocumentoControl anterior=d.getEstado();d.setEstado(EstadoDocumentoControl.ANULADO);d.setObservaciones(unir(d.getObservaciones(),"ANULADO: "+t(observaciones)));write.save(d);auditoria.registrarDespuesDeConfirmar(TipoAccion.UPDATE,"DOCUMENTO_CAJA",d.getId(),"Anulación de documento de caja",Map.of("estado",anterior),Map.of("estado",d.getEstado()));}
 public List<DocumentoCajaResponse> listar(UUID fincaId){TenantValidator.validateReadAccess(fincaId);return read.findByFincaIdOrderByFechaDesc(fincaId).stream().map(this::dto).toList();}
 public DocumentoCajaResponse obtener(UUID id){DocumentoCaja d=read.findById(id).orElseThrow(()->new IllegalArgumentException("Documento de caja no encontrado."));TenantValidator.validateReadAccess(d.getFincaId());return dto(d);}
 private DocumentoCajaResponse dto(DocumentoCaja d){return DocumentoCajaResponse.builder().id(d.getId()).numero(d.getNumero()).fincaId(d.getFincaId()).tipo(d.getTipo()).fecha(d.getFecha()).importe(d.getImporte()).beneficiario(d.getBeneficiario()).concepto(d.getConcepto()).entregadoPor(d.getEntregadoPor()).recibidoPor(d.getRecibidoPor()).autorizadoPor(d.getAutorizadoPor()).referencia(d.getReferencia()).observaciones(d.getObservaciones()).estado(d.getEstado()).build();}
 private void movimientoCaja(DocumentoCaja d,SentidoCaja sentido,Map<Integer,Integer> ds){if(sentido==SentidoCaja.EGRESO)for(var e:ds.entrySet()){SaldoCajaDenominacion s=saldoWrite.findByFincaIdAndDenominacionForUpdate(d.getFincaId(),e.getKey()).orElseThrow(()->new IllegalArgumentException("No existen billetes de "+e.getKey()+" CUP en caja."));if(s.getCantidad()<e.getValue())throw new IllegalArgumentException("No hay suficientes billetes de "+e.getKey()+" CUP en caja.");}MovimientoCaja m=new MovimientoCaja();m.setId(UUID.randomUUID());m.setFincaId(d.getFincaId());m.setFecha(d.getFecha());m.setTipo(sentido==SentidoCaja.INGRESO?TipoMovimientoCaja.DOCUMENTO_CAJA_INGRESO:TipoMovimientoCaja.DOCUMENTO_CAJA_EGRESO);m.setImporte(sentido==SentidoCaja.INGRESO?d.getImporte():-d.getImporte());m.setDocumentoCajaId(d.getId());m.setUsuarioId(TenantContext.getUsuarioId());m.setCreatedAt(LocalDateTime.now());m.setObservaciones("Documento de caja No. "+d.getNumero()+": "+d.getConcepto());cajaWrite.save(m);for(var e:ds.entrySet()){int delta=sentido==SentidoCaja.INGRESO?e.getValue():-e.getValue();SaldoCajaDenominacion s=saldoWrite.findByFincaIdAndDenominacionForUpdate(d.getFincaId(),e.getKey()).orElseGet(()->{SaldoCajaDenominacion n=new SaldoCajaDenominacion();n.setId(UUID.randomUUID());n.setFincaId(d.getFincaId());n.setDenominacion(e.getKey());n.setCantidad(0);return n;});s.setCantidad(s.getCantidad()+delta);saldoWrite.save(s);MovimientoCajaDenominacion x=new MovimientoCajaDenominacion();x.setId(UUID.randomUUID());x.setMovimientoCajaId(m.getId());x.setDenominacion(e.getKey());x.setCantidad(delta);detalleWrite.save(x);}Map<String,Object> datos=new LinkedHashMap<>();datos.put("fincaId",m.getFincaId());datos.put("tipo",m.getTipo());datos.put("importe",m.getImporte());datos.put("documentoCajaId",d.getId());datos.put("denominaciones",ds);auditoria.registrarDespuesDeConfirmar(TipoAccion.PAYMENT,"MOVIMIENTO_CAJA",m.getId(),"Movimiento de caja respaldado por documento",Map.of("importe",0d),datos);}
 private Map<Integer,Integer> denominaciones(DocumentoCajaRequest r){if(r.getSentidoCaja()==null)throw new IllegalArgumentException("Debe indicar si el documento INGRESA o EGRESA efectivo de Caja.");Map<Integer,Integer> out=new LinkedHashMap<>();for(DenominacionCajaDto x:Optional.ofNullable(r.getDenominaciones()).orElse(List.of())){if(x==null||x.getDenominacion()==null||!DENOMS.contains(x.getDenominacion())||x.getCantidad()==null||x.getCantidad()<=0)throw new IllegalArgumentException("Las denominaciones CUP deben ser válidas y positivas.");out.merge(x.getDenominacion(),x.getCantidad(),Math::addExact);}if(out.isEmpty())throw new IllegalArgumentException("El movimiento de caja requiere el desglose por denominación.");double total=out.entrySet().stream().mapToDouble(e->e.getKey()*e.getValue()).sum();if(Math.abs(total-r.getImporte())>EPS)throw new IllegalArgumentException("Las denominaciones deben sumar exactamente el importe del documento.");return out;}
 private void validar(DocumentoCajaRequest r){if(r==null||r.getFincaId()==null||r.getTipo()==null||r.getImporte()==null||r.getImporte()<=0||t(r.getBeneficiario())==null||t(r.getConcepto())==null)throw new IllegalArgumentException("Finca, tipo, importe positivo, beneficiario y concepto son obligatorios.");} private void finca(UUID id){if(!fincas.existsById(id))throw new IllegalArgumentException("Finca no encontrada.");} private String t(String x){return x==null||x.trim().isEmpty()?null:x.trim();} private String unir(String a,String b){return b==null?a:a==null?b:a+" | "+b;}
}
